from pathlib import Path
import os
def find_repositories(root):
 found=[]
 for base, dirs, files in os.walk(root):
  if (Path(base)/".git").is_dir():
   found.append(str(Path(base).relative_to(root))); dirs.clear()
 return sorted(found)
